		return this.appender.list.stream().map(ILoggingEvent::getFormattedMessage).toList();
	}

	public boolean anyContains(String... substrings) {
		return messages().stream().anyMatch(m -> {
			for (String s : substrings) {
				if (!m.contains(s)) {
